const decodeHtml = (s) =>
  (s || '')
    .replace(/&amp;/g, '&')
    .replace(/&nbsp;/g, ' ')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');

const clean = (s) =>
  decodeHtml(s || '')
    .replace(/<[^>]+>/g, '')
    .replace(/\s+/g, ' ')
    .trim();

const grupoOferta = $('DEFINE GRUPO').item.json.grupoOferta;

const extractMoney = (block) => {
  if (!block) return { texto: null, valor: null };
  const fracMatch = block.match(
    /data-andes-money-amount-fraction="true"[^>]*>([^<]+)</
  );
  const centsMatch = block.match(
    /data-andes-money-amount-cents="true"[^>]*>([^<]+)</
  );
  if (!fracMatch) return { texto: null, valor: null };

  const fracRaw = fracMatch[1].trim();
  const centsRaw = centsMatch ? centsMatch[1].trim() : null;

  const texto = centsRaw ? `R$ ${fracRaw},${centsRaw}` : `R$ ${fracRaw}`;

  const fracDigits = fracRaw.replace(/\D/g, '');
  const centsDigits = centsRaw ? centsRaw.replace(/\D/g, '') : null;
  const numericString = centsDigits
    ? `${fracDigits}.${centsDigits}`
    : fracDigits;
  const valor = parseFloat(numericString);

  return { texto, valor: Number.isFinite(valor) ? valor : null };
};

const extractProducts = (html) => {
  const products = [];
  const seen = new Set();

  const cardStartRegex = /<div\b[^>]*class="[^"]*\bpoly-card\b[^"]*"[^>]*>/g;
  const cardStarts = [];

  let m;
  while ((m = cardStartRegex.exec(html)) !== null) {
    cardStarts.push(m.index);
  }

  for (let i = 0; i < cardStarts.length; i++) {
    const card = html.slice(cardStarts[i], cardStarts[i + 1] || html.length);

    const titleMatch = card.match(
      /<a\b([^>]*class="[^"]*\bpoly-component__title\b[^"]*"[^>]*)>([\s\S]*?)<\/a>/
    );
    let title = null;
    let productUrl = null;
    if (titleMatch) {
      const hrefMatch = titleMatch[1].match(/href="([^"]+)"/);
      productUrl = hrefMatch ? decodeHtml(hrefMatch[1]) : null;
      title = clean(titleMatch[2]);
    }

    const imgMatch = card.match(
      /<img\b([^>]*class="[^"]*\bpoly-component__picture\b[^"]*"[^>]*)\/?>/
    );
    let imageUrl = null;
    if (imgMatch) {
      const srcMatch = imgMatch[1].match(/\ssrc="([^"]+)"/);
      const dataSrcMatch = imgMatch[1].match(/\sdata-src="([^"]+)"/);
      imageUrl = srcMatch ? srcMatch[1] : dataSrcMatch ? dataSrcMatch[1] : null;
    }

    const oldPriceBlock = card.match(
      /<s\s[^>]*andes-money-amount--previous[\s\S]*?<\/s>/
    );
    const previous = extractMoney(oldPriceBlock ? oldPriceBlock[0] : null);

    const currentContainer = card.match(
      /<div class="poly-price__current">([\s\S]*?)<\/div>/
    );
    const current = extractMoney(currentContainer ? currentContainer[1] : null);

    const discountMatch = card.match(
      /<span[^>]*class="[^"]*poly-price__disc_label[^"]*"[^>]*>([\s\S]*?)<\/span>/
    );
    const discount = discountMatch ? clean(discountMatch[1]) : null;

    if (!title) continue;

    const dedupKey = `${title}|${current.texto}|${imageUrl}`;
    if (seen.has(dedupKey)) continue;
    seen.add(dedupKey);

    products.push({
      nomeProduto: title,
      imagemProduto: imageUrl,
      urlOriginal: productUrl,
      precoAtual: current.texto,
      preco_atual_numero: current.valor,
      precoOriginal: previous.texto,
      preco_original_numero: previous.valor,
      desconto: discount,
      grupoOferta 
    });
  }

  return products;
};

const output = [];

for (const [itemIndex, item] of $input.all().entries()) {
  const json = item.json || {};
  const html = json.data || json.body || json.html || '';

  for (const product of extractProducts(html)) {
    output.push({
      json: product,
      pairedItem: { item: itemIndex },
    });
  }
}

return output;

const clean = (s) =>
  (s || '')
    .replace(/<[^>]+>/g, '')
    .replace(/&amp;/g, '&')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

const toNumber = (priceText) => {
  if (!priceText) return null;
  const onlyDigits = priceText
    .replace(/[^\d,]/g, '')
    .replace(',', '.');
  const n = parseFloat(onlyDigits);
  return Number.isFinite(n) ? n : null;
};

const grupoOferta = $('DEFINE GRUPO').item.json.grupoOferta;

const extractProducts = (html) => {
  const products = [];
  const seen = new Set();

  const cardRegex =
    /<div class="dynamic-carousel__item-container">[\s\S]*?<h3 class="dynamic-carousel__title">([\s\S]*?)<\/h3>/g;

  let match;
  while ((match = cardRegex.exec(html)) !== null) {
    const block = match[0];
    const title = clean(match[1]);

    const linkMatch = block.match(/<a class="splinter-link"\s+href="([^"]+)"/);
    const productUrl = linkMatch ? linkMatch[1] : null;

    const imgMatch = block.match(/<img[^>]*\ssrc="([^"]+)"/);
    const imageUrl = imgMatch ? imgMatch[1] : null;

    const oldPriceMatch = block.match(
      /<span\s+class="dynamic-carousel__oldprice">([^<]+)<\/span>/
    );
    const originalPriceText = oldPriceMatch ? clean(oldPriceMatch[1]) : null;

    const priceMatch = block.match(
      /<span class="dynamic-carousel__price">[\s\S]*?<span>([^<]+)<\/span>(?:\s*<sup class="dynamic-carousel__price-decimals">([^<]+)<\/sup>)?/
    );
    let currentPriceText = null;
    if (priceMatch) {
      const intPart = clean(priceMatch[1]);
      const decimals = priceMatch[2] ? clean(priceMatch[2]) : null;
      currentPriceText = decimals ? `${intPart},${decimals}` : intPart;
    }

    const discountMatch = block.match(
      /<sup\s+class="dynamic-carousel__discount">([^<]+)<\/sup>/
    );
    const discountText = discountMatch ? clean(discountMatch[1]) : null;

    const dedupKey = `${title}|${currentPriceText}|${imageUrl}`;
    if (seen.has(dedupKey)) continue;
    seen.add(dedupKey);

    products.push({
      nomeProduto: title,
      imagemProduto: imageUrl,
      urlOriginal: productUrl,
      precoAtual: currentPriceText,
      preco_atual_numero: toNumber(currentPriceText),
      precoOriginal: originalPriceText,
      preco_original_numero: toNumber(originalPriceText),
      desconto: discountText,
      grupoOferta
    });
  }

  return products;
};

const output = [];

for (const [itemIndex, item] of $input.all().entries()) {
  const json = item.json || {};
  const html = json.data || json.body || json.html || '';

  for (const product of extractProducts(html)) {
    output.push({
      json: product,
      pairedItem: { item: itemIndex },
    });
  }
}

return output;

function formatarPreco(preco_original, preco_atual, desconto) {
  return `${preco_original || ""}\n${preco_atual || ""} ${desconto || ""}`;
}

for (const item of $input.all()) {
  // Pega o link, garantindo que seja uma string
  const urlOriginal = item.json.urlOriginal ? item.json.urlOriginal.toString() : "";

  item.json.preco = formatarPreco(item.json.precoOriginal,
                                 item.json.precoAtual,
                                 item.json.desconto);

  // 1. Extração do ID (Correção aqui)
  // A regex /MLB-?\d+/i aceita "MLB123" E "MLB-123"
  const matchId = urlOriginal.match(/MLB-?\d+/i);

  if (matchId) {
    // Se tiver hífen, removemos para padronizar tudo como "MLB12345" no banco
    item.json.idProduto = matchId[0].replace('-', '').toUpperCase();
  } else {
    item.json.idProduto = "SEM_ID";
  }
}

return $input.all();

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.urlOriginal = item.json.urlOriginal.split('?')[0];
}

return $input.all();

